/* Daily Gambit — translations (English is the key; [Slovak, German]) */
var LANG='sk';
var LOCALES={sk:'sk-SK',de:'de-DE',en:'en-GB'};
function setLang(l){ LANG=(l==='en'||l==='de'||l==='sk')?l:'sk'; try{ document.documentElement.lang=LANG; }catch(e){} }
function t(en,v){
  var row=DICT[en], s=en;
  if(row){ if(LANG==='sk'&&row[0]) s=row[0]; else if(LANG==='de'&&row[1]) s=row[1]; }
  if(v) s=s.replace(/\{(\w+)\}/g,function(m,k){ return v[k]!=null?v[k]:m; });
  return s;
}
