var SANMAP={sk:{K:'K',Q:'D',R:'V',B:'S',N:'J'},de:{K:'K',Q:'D',R:'T',B:'L',N:'S'}};
function ls(san){ var m=SANMAP[LANG]; if(!m||san==null) return san; return String(san).replace(/[KQRBN]/g,function(c){return m[c]}); }
